13v &= -39
\end{align*}

Now, we can solve for $v$:
\begin{align*}
v &= \frac{-39}{13} \\
v &= -3
\end{align*}

Substituting the value of $v$ back into equation (2), we can solve for $u$:
\begin{align*}
2u + 4(-3) &= -8 \\
2u - 12 &= -8 \\
2u &= -8 + 12 \\
2u &= 4 \\
u &= \frac{4}{2} \\
u &= 2
\end{align*}

Finally, we can find the value of $u+v$:
\begin{align*}
u + v &= 2 + (-3) \\
u + v &= -1
\end{align*}

Therefore, the value of $u+v$ is $\boxed{-1}$.

